$(document).ready(function(){$("#menuToggle").on("click",function(){$("#mobileMenu").removeClass("-translate-x-full").addClass("translate-x-0")}),$("#menuClose").on("click",function(){$("#mobileMenu").removeClass("translate-x-0").addClass("-translate-x-full")}),$("#searchTours").on("click",function(){const n=$("#destination").val();n?(console.log(`Searching tours for destination: ${n}`),window.location.href=`/destination/${encodeURIComponent(n)}/`):(console.log("No destination entered."),alert("Please enter a destination to search for tours."))})});